	static readonly Dictionary<string, FontWidthData> fontWidthDataDict = new Dictionary<string, FontWidthData>();

	internal static double[] GetFontWidthData(string fontName, FontStyle fontStyle, float fontSize, ref int height)
	{
		var fontWidthData = FindFontWidthData(fontName, fontStyle, fontSize);

		if (!fontWidthData.Equals(default(FontWidthData)))
		{
			return fontWidthData.FontData;
		}

		var replacementFontSize = fontWidthDict.Where(f => f.FontName == fontName && f.FontStyle == fontStyle && f.FontSize < fontSize).Select(f => f.FontSize).DefaultIfEmpty().Max();
		if (replacementFontSize == 0)
		{
			replacementFontSize = fontWidthDict.Where(f => f.FontName == fontName && f.FontStyle == fontStyle && f.FontSize > fontSize).Select(f => f.FontSize).DefaultIfEmpty().Min();
		}
		if (replacementFontSize == 0)
		{
			var replacementFont = new Font(DefaultFontName, DefaultFontSize, fontStyle);
			height = replacementFont.GetFontHeight();

			Application.ReportDeveloperException($"Font not found - {FontFullName(fontName, fontStyle, fontSize)}. The Error occured in Winzor TextSizeCaching GetFontWidthData method.");

			return FindFontWidthData(DefaultFontName, fontStyle, DefaultFontSize).FontData;
		}

		fontWidthData = FindFontWidthData(fontName, fontStyle, replacementFontSize);

		var fontWidthList = new List<double>();
		for (var i = 0; i < fontWidthData.FontData.Length; i++)
		{
			fontWidthList.Add(fontWidthData.FontData[i] * fontSize / replacementFontSize);
		}

		return fontWidthList.ToArray();
	}

	static FontWidthData FindFontWidthData(string fontName, FontStyle fontStyle, double fontSize)
	{
		if (fontWidthDataDict.TryGetValue(FontFullName(fontName, fontStyle, fontSize), out FontWidthData fontWidthData))
		{
			return fontWidthData;
		}

		return default(FontWidthData);
	}

	static string FontFullName(string fontName, FontStyle fontStyle, double fontSize) => $"{fontName}_{FontStyleString(fontStyle)}_{fontSize}";

	static string FontStyleString(FontStyle fontStyle) => fontStyle == FontStyle.Regular ? "Normal" : fontStyle.ToString();

	public static bool IsFontSupported(string fontName) => fontWidthDict.Any(f => f.FontName == fontName);
}

internal struct FontWidthData
{
	public string FontName { get; private set; }
	public FontStyle FontStyle { get; private set; }
	public double FontSize { get; private set; }
	public double[] FontData { get; private set; }

	internal FontWidthData(string fontName, FontStyle fontStyle, double fontSize, double[] fontData)
	{
		FontName = fontName;
		FontStyle = fontStyle;
		FontSize = fontSize;
		FontData = fontData;
	}
}
